public event function Activated()
{
    local int MissionCount;
    local BioGlobalVariableTable gv;
    local string CurrentMap;
    local LeaveMissionData LeaveMission;
    local WorldInfo WorldInfo;
    local PlayerController PC;
    local SFXPlayerController SPC;
    local SFXPawn_Player pPawn;
    local Name AchievementMapCode;
    local array<TelemetryAttribute> aTelAttribs;

    WorldInfo = Class'WorldInfo'.static.GetWorldInfo();
    if (WorldInfo != None)
    {
        PC = WorldInfo.GetALocalPlayerController();
        if (PC != None)
        {
            pPawn = SFXPawn_Player(PC.Pawn);
        }
        SPC = SFXPlayerController(PC);
    }
    Class'SFXSystem'.static.ResetGlobalReaperAlertLevels();
    GrantAutomaticGawAssets();
    if (pPawn != None && SFXInventoryManager(pPawn.InvManager) != None)
    {
        SFXInventoryManager(pPawn.InvManager).RemoveHeavyWeapons();
    }
    gv = getWorld().GetGlobalVariables();
    MissionCount = gv.GetInt(10165) + 1;
    gv.SetInt(10165, MissionCount);
    CurrentMap = getWorld().GetMapName();
    LogInternal("Leave Mission: Current Map " $ CurrentMap, );
    switch (Name(CurrentMap))
    {
        case 'Biop_ProEar':
            AchievementMapCode = 'ProEar';
            break;
        case 'Biop_ProMar':
            AchievementMapCode = 'ProMar';
            break;
        case 'Biop_Gth001':
            AchievementMapCode = 'Gth001';
            break;
        case 'Biop_Gth002':
            AchievementMapCode = 'Gth002';
            break;
        case 'Biop_GthLeg':
            AchievementMapCode = 'GthLeg';
            break;
        case 'Biop_KroGar':
            AchievementMapCode = 'KroGar';
            break;
        case 'Biop_Kro001':
            AchievementMapCode = 'Kro001';
            break;
        case 'Biop_Kro002':
            AchievementMapCode = 'Kro002';
            break;
        case 'Biop_KroGru':
            AchievementMapCode = 'KroGru';
            break;
        case 'Biop_Cat002':
            AchievementMapCode = 'Cat002';
            break;
        case 'Biop_Cat003':
            AchievementMapCode = 'Cat003';
            break;
        case 'Biop_Cat004':
            AchievementMapCode = 'Cat004';
            break;
        case 'Biop_CerMir':
            AchievementMapCode = 'CerMir';
            break;
        case 'Biop_CerJcb':
            AchievementMapCode = 'CerJcb';
            break;
        case 'Biop_CitSam':
            AchievementMapCode = 'CitSam';
            break;
        case 'Biop_OmgJck':
            AchievementMapCode = 'OmgJck';
            break;
        case 'Biop_End001':
            AchievementMapCode = 'End001';
            break;
        case 'Biop_End002':
            AchievementMapCode = 'END002';
            break;
        default:
    }
    if (SPC != None)
    {
        if (AchievementMapCode != 'None')
        {
            SPC.UnlockAccomplishment(AchievementMapCode);
        }
    }
    foreach LeaveMissionArray(LeaveMission, )
    {
        if (CurrentMap == string(LeaveMission.CurrentMap))
        {
            if (LeaveMission.EndGmAct != 0)
            {
                gv.SetInt(10161, LeaveMission.EndGmAct);
                gv.SetInt(10162, LeaveMission.EndGmAct);
                gv.SetInt(10163, LeaveMission.EndGmAct);
                gv.SetFloat(10041, LeaveMission.EndGmX);
                gv.SetFloat(10042, LeaveMission.EndGmY);
            }
            aTelAttribs.Add(3);
            aTelAttribs[0].Type = 1;
            aTelAttribs[0].Name = "moment";
            aTelAttribs[0].sData = "mission_complete";
            aTelAttribs[1].Type = 1;
            aTelAttribs[1].Name = "mstid";
            aTelAttribs[1].sData = CurrentMap;
            aTelAttribs[2].Type = 1;
            aTelAttribs[2].Name = "type";
            aTelAttribs[2].sData = "mission";
            Class'SFXTelemetry'.static.SendArray('Hook_Milestone', aTelAttribs);
            LogInternal("Leave Mission: Moving to map " $ LeaveMission.NextMap, );
            getWorld().MoveToArea(LeaveMission.NextMap, LeaveMission.NextStart);
        }
    }
}

public final function GrantAutomaticGawAssets()
{
    local WorldInfo WI;
    local SFXGame Game;
    local TD LevelTreasure;
    local string MissionName;
    local SFXGAWAssetsHandler GAWHandler;
    local int idx;

    WI = Class'WorldInfo'.static.GetWorldInfo();
    if (WI == None)
    {
        return;
    }
    Game = SFXGame(WI.Game);
    if (Game == None)
    {
        return;
    }
    GAWHandler = Class'SFXGAWAssetsHandler'.static.GetGAWHandler();
    if (GAWHandler == None)
    {
        return;
    }
    MissionName = WI.GetMapName();
    foreach Game.TREASURE.LevelTreasure(LevelTreasure, )
    {
        if (Locs(LevelTreasure.Level) == Locs(MissionName))
        {
            for (idx = 0; idx < LevelTreasure.TREASURE.Length; idx++)
            {
                if (Split(LevelTreasure.TREASURE[idx], "GAWAsset", TRUE) != LevelTreasure.TREASURE[idx])
                {
                    GAWHandler.UnlockGAWAssetByAssetName(LevelTreasure.TREASURE[idx]);
                }
            }
            return;
        }
    }
}
